package com.skillforge.platform.controller;

import com.skillforge.platform.dto.ApiResponse;
import com.skillforge.platform.entity.SkillPackage;
import com.skillforge.platform.entity.User;
import com.skillforge.platform.service.PackageService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/packages")
public class PackageController {

    private final PackageService packageService;

    public PackageController(PackageService packageService) {
        this.packageService = packageService;
    }

    @PostMapping("/upload")
    public ResponseEntity<ApiResponse<Map<String, Object>>> upload(
            @RequestParam("file") MultipartFile file,
            Authentication authentication) {
        SkillPackage uploaded = packageService.upload(principal(authentication), file);
        Map<String, Object> data = new LinkedHashMap<String, Object>();
        data.put("id", uploaded.getId());
        data.put("status", uploaded.getStatus());
        data.put("originalFilename", uploaded.getOriginalFilename());
        data.put("createdAt", timestamp(uploaded.getCreatedAt()));
        return ResponseEntity.ok(ApiResponse.success("上传成功", data));
    }

    @PostMapping("/{id}/parse")
    public ResponseEntity<ApiResponse<Map<String, Object>>> parse(
            @PathVariable("id") Long id,
            Authentication authentication) {
        try {
            SkillPackage skillPackage = packageService.parse(id, principal(authentication));
            String message = "PARSED".equals(skillPackage.getStatus()) ? "解析成功" : "解析失败";
            return ResponseEntity.ok(ApiResponse.success(message, parseData(skillPackage)));
        } catch (PackageService.PackageLookupException exception) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(ApiResponse.error(400, exception.getMessage()));
        }
    }

    @GetMapping
    public ResponseEntity<ApiResponse<List<Map<String, Object>>>> list(
            Authentication authentication) {
        List<Map<String, Object>> data = new ArrayList<Map<String, Object>>();
        for (SkillPackage skillPackage : packageService.list(principal(authentication))) {
            Map<String, Object> item = new LinkedHashMap<String, Object>();
            item.put("id", skillPackage.getId());
            item.put("name", skillPackage.getName());
            item.put("version", skillPackage.getVersion());
            item.put("status", skillPackage.getStatus());
            item.put("createdAt", timestamp(skillPackage.getCreatedAt()));
            data.add(item);
        }
        return ResponseEntity.ok(ApiResponse.success(data));
    }

    @GetMapping("/{id}")
    public ResponseEntity<ApiResponse<Map<String, Object>>> detail(
            @PathVariable("id") Long id,
            Authentication authentication) {
        try {
            SkillPackage skillPackage = packageService.detail(id, principal(authentication));
            Map<String, Object> data = parseData(skillPackage);
            data.put("originalFilename", skillPackage.getOriginalFilename());
            data.put("createdAt", timestamp(skillPackage.getCreatedAt()));
            Object parsedAt = data.remove("parsedAt");
            data.put("parsedAt", parsedAt);
            return ResponseEntity.ok(ApiResponse.success(data));
        } catch (PackageService.PackageLookupException exception) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(ApiResponse.error(404, exception.getMessage()));
        }
    }

    private Map<String, Object> parseData(SkillPackage skillPackage) {
        Map<String, Object> data = new LinkedHashMap<String, Object>();
        data.put("id", skillPackage.getId());
        data.put("name", skillPackage.getName());
        data.put("version", skillPackage.getVersion());
        data.put("description", skillPackage.getDescription());
        data.put("author", skillPackage.getAuthor());
        data.put("category", skillPackage.getCategory());
        data.put("status", skillPackage.getStatus());
        data.put("parsedAt", timestamp(skillPackage.getParsedAt()));
        return data;
    }

    private User principal(Authentication authentication) {
        return (User) authentication.getPrincipal();
    }

    private String timestamp(LocalDateTime value) {
        return value == null ? null : value.toString();
    }
}

